package com.lyra.studio; import android.app.Activity; import android.view.WindowManager; import com.google.appinventor.components.annotations.*; import com.google.appinventor.components.common.*; import com.google.appinventor.components.runtime.*; @DesignerComponent(version = 1, description = "Extensao para WebViewer com recursos avancados e ajuste de teclado virtual.", category = ComponentCategory.EXTENSION, nonVisible = true, iconName = "images/extension.png") @SimpleObject(external = true) public class AdvancedWebViewer extends AndroidNonvisibleComponent { private final Activity activity; public AdvancedWebViewer(ComponentContainer container) { super(container.$form()); this.activity = container.$context(); } @SimpleFunction(description = "Ajusta a tela para que o teclado virtual nao cubra o conteudo do WebViewer.") public void EnableKeyboardResize() { /* Define o modo de entrada suave para redimensionar a tela quando o teclado aparece */ activity.runOnUiThread(new Runnable() { @Override public void run() { activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE); } }); } @SimpleFunction(description = "Restaura o comportamento padrao do teclado virtual.") public void DisableKeyboardResize() { /* Restaura o comportamento para o padrao pan ou unspecified */ activity.runOnUiThread(new Runnable() { @Override public void run() { activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_PAN); } }); } }